5	/// Detail screen for one season of a TV show. Lists episodes via `EpisodeRowView` and supports
6	/// per-episode and "mark season watched" toggles when the show is on the user's watchlist.
7	struct SeasonDetailView: View {
8	    let mediaId: Int
9	    let season: TVSeason
10	    /// Whether the parent show is currently in the user's watchlist. Drives whether episode
11	    /// toggles are interactive.
12	    let isInWatchlist: Bool
13	
14	    @Environment(\.modelContext) private var modelContext
15	    @Query private var watchedEpisodes: [WatchedEpisode]
16	
17	    @State private var seasonDetails: SeasonDetails?
18	    @State private var isLoading = true
19	    @State private var errorMessage: String?
20	
21	    private let service: TMDBService? = try? TMDBService()
22	
23	    init(mediaId: Int, season: TVSeason, isInWatchlist: Bool) {
24	        self.mediaId = mediaId
25	        self.season = season
26	        self.isInWatchlist = isInWatchlist
27	
28	        let seasonNum = season.seasonNumber
29	        _watchedEpisodes = Query(filter: #Predicate<WatchedEpisode> { ep in
30	            ep.mediaId == mediaId && ep.seasonNumber == seasonNum
31	        })
32	    }
33	
34	    private var episodes: [Episode] {
35	        seasonDetails?.episodes ?? []
36	    }
37	
38	    private var watchedEpisodeIDs: Set<Int> {
39	        Set(watchedEpisodes.map(\.episodeId))
40	    }
41	
42	    private var watchedCount: Int {
43	        guard isInWatchlist else { return 0 }
44	        return watchedEpisodes.count
45	    }
46	
47	    private var allWatched: Bool {
48	        !episodes.isEmpty && watchedCount == episodes.count
49	    }
50	
51	    var body: some View {
52	        Group {
53	            if isLoading {
54	                ProgressView("Loading episodes...")
55	            } else if let errorMessage {
56	                ContentUnavailableView {
57	                    Label("Unable to Load", systemImage: "exclamationmark.triangle")
58	                } description: {
59	                    Text(errorMessage)
60	                } actions: {
61	                    Button("Retry") {
62	                        Task { await loadSeasonDetails() }
63	                    }
64	                }
65	            } else {
66	                List {
67	                    Section {
68	                        ForEach(episodes, id: \.id) { episode in
69	                            EpisodeRowView(
70	                                episode: episode,
71	                                mediaId: mediaId,
72	                                isInWatchlist: isInWatchlist,
73	                                isWatched: watchedEpisodeIDs.contains(episode.id)
74	                            )
75	                        }
76	                    }
77	                }
78	                .listStyle(.insetGrouped)
79	            }
80	        }
81	        .navigationTitle(season.name)
82	        .navigationBarTitleDisplayMode(.inline)
83	        .toolbar {
84	            if isInWatchlist && !episodes.isEmpty {
85	                ToolbarItem(placement: .topBarTrailing) {
86	                    Button {
87	                        if allWatched {
88	                            WatchlistManager.shared.markSeasonUnwatched(
89	                                mediaId: mediaId,
90	                                seasonNumber: season.seasonNumber,
91	                                context: modelContext
92	                            )
93	                        } else {
94	                            WatchlistManager.shared.markSeasonWatched(
95	                                mediaId: mediaId,
96	                                episodes: episodes,
97	                                context: modelContext
98	                            )
99	                        }
100	                        HapticManager.success()
101	                    } label: {
102	                        Text(allWatched ? "Mark All Unwatched" : "Mark All Watched")
103	                    }
104	                }
105	            }
106	        }
107	        .task {
108	            await loadSeasonDetails()
109	        }
110	    }
111	
112	    private func loadSeasonDetails() async {
113	        guard let service else {
114	            errorMessage = "API key not configured"
115	            isLoading = false
116	            return
117	        }
118	
119	        isLoading = true
120	        errorMessage = nil
121	
122	        do {
123	            seasonDetails = try await service.getSeasonDetails(
124	                tvId: mediaId,
125	                seasonNumber: season.seasonNumber
126	            )
127	        } catch {
128	            errorMessage = error.localizedDescription
129	        }
130	
131	        isLoading = false
132	    }
133	}
