27	    /// Maps a `UIApplicationShortcutItem.type` to an `AppTab` and stores it as `pendingAction`.
28	    /// Unrecognized shortcut types are silently ignored.
29	    func handleShortcutItem(_ shortcutItem: UIApplicationShortcutItem) {
30	        switch shortcutItem.type {
31	        case "SearchAction":
32	            pendingAction = .search
33	        case "TrendingAction":
34	            pendingAction = .trending
35	        case "SavedAction":
36	            pendingAction = .watchlist
