43	final class AppDelegate: NSObject, UIApplicationDelegate {
44	    func application(
45	        _ application: UIApplication,
46	        didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]? = nil
47	    ) -> Bool {
48	        // Register notification categories and background tasks
49	        NotificationManager.registerCategories()
50	        BackgroundTaskManager.shared.registerTasks()
51	
52	        // Set notification delegate for handling taps
53	        UNUserNotificationCenter.current().delegate = NotificationDelegate.shared
54	
55	        // Schedule background availability check
56	        BackgroundTaskManager.shared.scheduleAvailabilityCheck()
57	
58	        return true
59	    }
60	
61	    func application(
62	        _ application: UIApplication,
63	        configurationForConnecting connectingSceneSession: UISceneSession,
64	        options: UIScene.ConnectionOptions
65	    ) -> UISceneConfiguration {
66	        // Handle shortcut item if app was launched from Quick Action
67	        if let shortcutItem = options.shortcutItem {
68	            // Store synchronously so it's available when view appears
69	            DispatchQueue.main.async {
70	                QuickActionManager.shared.handleShortcutItem(shortcutItem)
71	            }
72	        }
73	
74	        let configuration = UISceneConfiguration(name: nil, sessionRole: connectingSceneSession.role)
75	        configuration.delegateClass = SceneDelegate.self
